base=Path(sys.argv[1]) if len(sys.argv)>1 else Path('.')
def readings(s):
 pattern=r'<script>/\* Furigana for the built-in Japanese interface\..*?</script>'
 s,n=re.subn(pattern,lambda m:'<script>'+RUBY+'</script>',s,flags=re.S)
 if not n:
  prefix,suffix=s.rsplit('</body>',1);s=prefix+'<script>'+RUBY+'</script></body>'+suffix
 return s
for name in ('nanpure.html','nanpure/index.html'):
 p=base/name;s=p.read_text(encoding='utf-8')
 s=re.sub(r'<script id="np-help-update">.*?</script>','',s,flags=re.S)
 assert '<dialog id="options"' in s and 'const shellCatalog=' in s, name+' has an unexpected structure'
 for m in list(re.finditer(r'(<script id="page-[^"]+" type="application/json">)(.*?)(</script>)',s,re.S))[::-1]:
  page=readings(json.loads(m[2]));s=s[:m.start(2)]+json.dumps(page,ensure_ascii=False).replace('<','\\u003c')+s[m.end(2):]
 s=readings(s)
 prefix,suffix=s.rsplit('</body>',1)
 p.write_text(prefix+'<script id="np-help-update">'+RUNTIME+'</script></body>'+suffix,encoding='utf-8');print('Updated',name)
